/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
// Load Fonts
import { makeLoadFont } from '../googleFonts';
const loadTeko = makeLoadFont('Teko');
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: tekoFamily } = loadTeko();
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();

// ------------------------------------------------------------------
// SCHEMA
// ------------------------------------------------------------------


export type MidnightRunLightLeakProps = Record<string, any>;

// ------------------------------------------------------------------
// DETERMINISTIC DATA FOR STREAKS & LEAKS
// ------------------------------------------------------------------
// We use hardcoded pseudo-random values to ensure pure, deterministic rendering.
const STREAKS = [
  { id: 1, xPos: 0.1, width: 0.02, hMult: 1.5, colorKey: "primaryGlowColor", speedMod: 1.2, delay: 0 },
  { id: 2, xPos: 0.85, width: 0.05, hMult: 2.0, colorKey: "secondaryGlowColor", speedMod: 1.8, delay: 45 },
  { id: 3, xPos: 0.3, width: 0.015, hMult: 1.0, colorKey: "headlightColor", speedMod: 2.5, delay: 12 },
  { id: 4, xPos: 0.6, width: 0.08, hMult: 1.8, colorKey: "primaryGlowColor", speedMod: 0.9, delay: 80 },
  { id: 5, xPos: 0.2, width: 0.03, hMult: 1.2, colorKey: "headlightColor", speedMod: 2.1, delay: 110 },
  { id: 6, xPos: 0.75, width: 0.04, hMult: 1.6, colorKey: "secondaryGlowColor", speedMod: 1.5, delay: 30 },
  { id: 7, xPos: 0.45, width: 0.01, hMult: 0.8, colorKey: "headlightColor", speedMod: 3.0, delay: 65 },
  { id: 8, xPos: 0.9, width: 0.06, hMult: 2.5, colorKey: "primaryGlowColor", speedMod: 1.1, delay: 140 },
] as const;

const BLOBS = [
  { id: 1, colorKey: "primaryGlowColor", phase: 0, speed: 0.02, size: 0.8, xAnchor: 0.2, yAnchor: 0.1 },
  { id: 2, colorKey: "secondaryGlowColor", phase: Math.PI / 2, speed: 0.015, size: 1.0, xAnchor: 0.8, yAnchor: 0.8 },
  { id: 3, colorKey: "headlightColor", phase: Math.PI, speed: 0.03, size: 0.6, xAnchor: 0.5, yAnchor: 0.5 },
] as const;

// ------------------------------------------------------------------
// COMPONENT
// ------------------------------------------------------------------
const MidnightRunLightLeak: React.FC<MidnightRunLightLeakProps> = ({
  backgroundColor = "#030303",
  transparentBackground = false,
  durationInSeconds = 8,
  primaryGlowColor = "#FF1E00", // Engine Heat Red
  secondaryGlowColor = "#00D4FF", // Night Neon Cyan
  headlightColor = "#FFFFFF", // Blinding White
  speedMultiplier = 1.0,
  intensity = 1.0,
  overlayText = "MIDNIGHT RUN",
  overlayTextFontFamily = "Teko",
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  // Parser-safe transparent background logic
  const actualBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Map enum to actual font family
  const selectedFontFamily = overlayTextFontFamily === "Space Grotesk" ? spaceGroteskFamily : tekoFamily;

  // Map color strings for easy access by deterministic data
  const colors: Record<string, string> = {
    primaryGlowColor,
    secondaryGlowColor,
    headlightColor,
  };

  const cycleFrames = 200; // Base frames for one full loop of a streak
  const s = Math.min(width, height);

  return (
    <AbsoluteFill style={{ backgroundColor: actualBgColor, overflow: "hidden" }}>
      
      {/* 
        ROTATED CONTAINER
        Gives the vertical streaks a dynamic, aggressive angle typical of motorcycle media 
        (leaning into a curve). 
      */}
      <div
        style={{
          position: "absolute",
          width: width * 2,
          height: height * 2,
          left: -width * 0.5,
          top: -height * 0.5,
          transform: "rotate(-12deg)",
          display: "flex",
          pointerEvents: "none",
        }}
      >
        {/* PASSING LIGHT STREAKS */}
        {STREAKS.map((streak) => {
          // Calculate a continuous looping progress from 0 to 1
          const rawProgress = ((frame * streak.speedMod * speedMultiplier) + streak.delay) % cycleFrames;
          const normalizedProgress = rawProgress / cycleFrames;

          // Move from top (offscreen) to bottom (offscreen)
          const yPos = interpolate(
            normalizedProgress,
            [0, 1],
            [-height * 1.5, height * 2.5]
          );

          // Fade in and out to prevent popping at the loop boundaries
          const streakOpacity = interpolate(
            normalizedProgress,
            [0, 0.1, 0.9, 1],
            [0, intensity * 0.8, intensity * 0.8, 0]
          );

          const streakColor = colors[streak.colorKey];
          const streakWidth = width * streak.width;
          const streakHeight = height * streak.hMult;

          return (
            <div
              key={`streak-${streak.id}`}
              style={{
                position: "absolute",
                left: width * 2 * streak.xPos,
                top: 0,
                width: streakWidth,
                height: streakHeight,
                backgroundColor: streakColor,
                transform: `translateY(${yPos}px)`,
                opacity: streakOpacity,
                mixBlendMode: "screen",
                borderRadius: "100px",
                filter: `blur(${streakWidth * 0.8}px)`,
                boxShadow: `0 0 ${streakWidth * 3}px ${streakWidth}px ${streakColor}`,
                transition: "none",
              }}
            />
          );
        })}
      </div>

      {/* AMBIENT LENS FLARES / LEAKS */}
      <AbsoluteFill style={{ mixBlendMode: "screen", pointerEvents: "none" }}>
        {BLOBS.map((blob) => {
          const blobColor = colors[blob.colorKey];
          
          // Organic hovering movement
          const xOffset = Math.sin(frame * blob.speed + blob.phase) * width * 0.3;
          const yOffset = Math.cos(frame * blob.speed * 0.8 + blob.phase) * height * 0.2;
          
          // Pulsing scale
          const scale = interpolate(
            Math.sin(frame * blob.speed * 1.5 + blob.phase),
            [-1, 1],
            [0.8, 1.3]
          );

          // Pulsing opacity
          const blobOpacity = interpolate(
            Math.sin(frame * blob.speed * 1.2 + blob.phase),
            [-1, 1],
            [0.1 * intensity, 0.5 * intensity]
          );

          const size = s * blob.size * 1.5;

          return (
            <div
              key={`blob-${blob.id}`}
              style={{
                position: "absolute",
                left: width * blob.xAnchor - size / 2,
                top: height * blob.yAnchor - size / 2,
                width: size,
                height: size,
                background: `radial-gradient(circle, ${blobColor} 0%, transparent 60%)`,
                opacity: blobOpacity,
                transform: `translate(${xOffset}px, ${yOffset}px) scale(${scale})`,
                transition: "none",
              }}
            />
          );
        })}
      </AbsoluteFill>

      {/* OPTIONAL OVERLAY TEXT */}
      {overlayText && (
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            pointerEvents: "none",
            zIndex: 10,
          }}
        >
          <h1
            style={{
              fontFamily: selectedFontFamily,
              color: "#FFFFFF",
              fontSize: s * 0.15,
              fontWeight: 800,
              textTransform: "uppercase",
              letterSpacing: "0.15em",
              textAlign: "center",
              margin: 0,
              padding: "0 5%",
              mixBlendMode: "overlay",
              opacity: interpolate(frame, [0, 30], [0, 0.9], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }),
              transform: `scale(${interpolate(frame, [0, durationInSeconds * 30], [0.95, 1.05])})`,
              textShadow: `0px 0px 40px rgba(255, 255, 255, 0.3)`,
              transition: "none",
            }}
          >
            {overlayText}
          </h1>
        </div>
      )}

    </AbsoluteFill>
  );
};

export default MidnightRunLightLeak;